/bin/bash -lc "python3 -m py_compile /workspace/openai_client.py && python3 - <<'PY'
import json
import urllib.request

from openai_client import OpenAIClient, _extract_text

captured = {}

class FakeResponse:
    status = 200
    def read(self):
        return json.dumps({
            \"status\": \"completed\",
            \"output\": [{
                \"type\": \"message\",
                \"content\": [{\"type\": \"output_text\", \"text\": \"Hello\"}],
            }],
        }).encode(\"utf-8\")
    def __enter__(self):
        return self
    def __exit__(self, exc_type, exc, traceback):
        return False

original_urlopen = urllib.request.urlopen
def fake_urlopen(request, timeout, context):
    captured[\"request\"] = request
    captured[\"timeout\"] = timeout
    captured[\"context\"] = context
    return FakeResponse()

urllib.request.urlopen = fake_urlopen
try:
    client = OpenAIClient(model=\"test-model\", api_key=\"test-key\", timeout=7)
    response = client.send_text(
        \"private prompt\",
        instructions=\"be brief\",
        max_output_tokens=12,
    )
finally:
    urllib.request.urlopen = original_urlopen

request = captured[\"request\"]
payload = json.loads(request.data)
assert response == \"Hello\"
assert captured[\"timeout\"] == 7.0
assert request.full_url == \"https://api.openai.com/v1/responses\"
assert request.get_header(\"Authorization\") == \"Bearer test-key\"
assert payload == {
    \"model\": \"test-model\",
    \"input\": \"private prompt\",
    \"instructions\": \"be brief\",
    \"max_output_tokens\": 12,
}
assert _extract_text({\"output\": []}) == \"\"
print(\"offline checks passed\")
PY"

